def test_command(self, command: str, params: Dict = None, timeout: float = 8.0) -> bool:
    """Test a single flight command"""
    if params is None:
        params = {}

    print(f"\n🎮 Testing {command} command...")

    # Record current event count
    events_before = len([e for e in self.events if e[0] == 'command_result'])

    # Send command
    self.client.emit('flight_command', {
        'command': command,
        'params': params
    })

    # Wait for response
    start_time = time.time()
    while time.time() - start_time < timeout:
        command_events = [e for e in self.events if e[0] == 'command_result']

        if len(command_events) > events_before:
            # Find the matching command result
            for event in reversed(command_events):
                result = event[1]
                if result.get('command') == command:
                    success = result.get('success', False)
                    error = result.get('error', 'none')

                    if success:
                        print(f"  ✅ {command} command successful")
                    else:
                        print(f"  ⚠️ {command} command failed: {error}")

                    return True  # Command was processed (success or failure)

        time.sleep(0.1)

    print(f"  ❌ {command} command timed out")
    return False

