            mavutil.mavlink.MAV_CMD_NAV_TAKEOFF, # command
            0,          # confirmation
            0,          # param1: minimum pitch (degrees)
            0,          # param2: empty
            0,          # param3: empty
            0,          # param4: yaw angle (degrees)
            0,          # param5: latitude (if zero, use current position)
            0,          # param6: longitude (if zero, use current position)  
