            'timestamp': time.time(),
            'message': f"Takeoff to {altitude}m sent successfully"
        }

    except Exception as e:
        error_msg = f"Takeoff command failed: {e}"
        if log_callback:
            log_callback("COMMAND_ERROR", details=error_msg)

